109: function breedDialog() {
110:   if(game.creatures.length<2)return toast('You need two creatures to breed.')
111:   const a=selected(), others=game.creatures.filter(c=>c.id!==a.id)
112:   showModal(`<button class="modal-close" data-action="close">×</button><div class="eyebrow">INHERITANCE LAB · GEN 0${(a.generation||0)+1}</div><h2>Pair a lineage</h2><p>Choose a second parent. Their expressed traits combine with ${esc(a.name)}'s DNA; mutation can create new adaptations.</p><div class="parent-preview"><div class="parent-chip"><i style="--creature-color:${phenotype(a.genome).bodyColor}"></i><span><b>${esc(a.name)}</b><small>SELECTED PARENT</small></span></div><span class="cross">×</span><select id="mate-select">${others.map(c=>`<option value="${esc(c.id)}">${esc(c.name)} · ${c.sex==='F'?'♀':'♂'} · GEN ${c.generation||0}</option>`).join('')}</select></div><div class="modal-actions"><button class="secondary-btn" data-action="close">CANCEL</button><button class="primary-btn" data-action="breed-confirm">CREATE OFFSPRING ↗</button></div>`)
113: }
114: function breed() {
115:   const parent=selected(), mate=game.creatures.find(c=>c.id===$('#mate-select')?.value)
116:   if(!mate)return closeModal()
