132: }
133: function startBattle() {
134:   const player=selected(), foe=game.creatures.find(c=>c.id===$('#foe-select')?.value)
135:   if(!foe)return closeModal()
136:   closeModal(); mode='arena'; tab='overview'
137:   battle={player,foe,hp:{player:maxHpOf(player),foe:maxHpOf(foe)},maxHp:{player:maxHpOf(player),foe:maxHpOf(foe)},sta:{player:maxStaminaOf(player),foe:maxStaminaOf(foe)},maxSta:{player:maxStaminaOf(player),foe:maxStaminaOf(foe)},guard:{player:false,foe:false},busy:false,turn:1}
138:   world.enterArena(player,foe); updateModeUI(); renderProfile(); renderBattle()
139: }
140: function updateModeUI() {
141:   document.querySelectorAll('[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===mode))
142:   $('#stage-title').textContent=mode==='arena'?'The Crucible':'The Verdant Hollow'
143:   $('#stage-kicker').textContent=mode==='arena'?'⚔ COMBAT ARENA':'◌ OPEN HABITAT'
144:   $('#scene-tag-text').textContent=mode==='arena'?'BATTLE IN PROGRESS':'ECOSYSTEM ACTIVE'
145:   $('.creature-count').style.display=mode==='arena'?'none':''
146:   $('[data-action="arena"]').innerHTML=mode==='arena'?'↩ RETURN TO HOLLOW <b>↗</b>':'⚔ ENTER ARENA <b>↗</b>'
