158: function applyMove(attacker, defender, move, done) {
159:   if(!battle||battle.finished)return
160:   if(move.type==='defend') {
161:     battle.guard[attacker]=true; battle.sta[attacker]=Math.min(battle.maxSta[attacker],battle.sta[attacker]+Math.abs(move.cost));
162:     toast(`${battle[attacker].name} braces and recovers stamina.`); done(); return
163:   }
164:   const cost=Math.max(0,move.cost)
165:   if(battle.sta[attacker]<cost) { battle.sta[attacker]=Math.min(battle.maxSta[attacker],battle.sta[attacker]+12); toast(`${battle[attacker].name} is winded and recovers 12 stamina.`); done(); return }
166:   battle.sta[attacker]-=cost
167:   if(Math.random()>move.acc) { toast(`${move.name} missed!`); done(); return }
168:   let damage=Math.round((10+move.power*16)*(0.78+statsOf(battle[attacker]).power/180)*(0.82+Math.random()*.36))
169:   if(move.crit&&Math.random()<move.crit)damage=Math.round(damage*1.5)
170:   if(battle.guard[defender]&&!move.pierce){damage=Math.ceil(damage*.48);battle.guard[defender]=false;toast(`${battle[defender].name} guarded the hit!`)}
171:   battle.hp[defender]=Math.max(0,battle.hp[defender]-damage)
