179:   }
180:   const cost=Math.max(0,move.cost)
181:   if(battle.sta[attacker]<cost) { battle.sta[attacker]=Math.min(battle.maxSta[attacker],battle.sta[attacker]+12); toast(`${battle[attacker].name} is winded and recovers 12 stamina.`); done(); return }
182:   battle.sta[attacker]-=cost
183:   if(Math.random()>move.acc) { toast(`${move.name} missed!`); done(); return }
184:   let damage=Math.round((10+move.power*16)*(0.78+statsOf(battle[attacker]).power/180)*(0.82+Math.random()*.36))
185:   if(move.crit&&Math.random()<move.crit)damage=Math.round(damage*1.5)
186:   if(battle.guard[defender]&&!move.pierce){damage=Math.ceil(damage*.48);battle.guard[defender]=false;toast(`${battle[defender].name} guarded the hit!`)}
