import { createRequire } from 'node:module'
import { mkdirSync } from 'node:fs'
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json')
const { chromium } = require('playwright')
const browser = await chromium.launch({ channel: 'chromium', headless: true, args: ['--enable-gpu', '--ignore-gpu-blocklist', '--use-angle=swiftshader'] })
const page = await browser.newPage({ viewport: { width: 1280, height: 800 }, deviceScaleFactor: 1 })
const errors = []
page.on('pageerror', e => errors.push(e.message))
await page.goto('http://127.0.0.1:3002', { waitUntil: 'networkidle' })
await page.locator('[data-action="discover"]').click()
await page.locator('.adapt-option input[value="antlers"]').check()
await page.locator('.adapt-option input[value="fins"]').check()
await page.locator('.adapt-option input[value="gills"]').check()
await page.locator('.adapt-option input[value="antennae"]').check()
const count = await page.locator('#adapt-count').innerText()
const fourthChecked = await page.locator('.adapt-option input[value="antennae"]').isChecked()
if (count.trim() !== '3 / 3 SELECTED' || fourthChecked) throw new Error(`Adaptation limit failed: ${count}; fourth checked=${fourthChecked}`)
await page.locator('[data-action="discover-confirm"]').click()
await page.waitForFunction(() => document.querySelectorAll('#roster [data-creature]').length === 4)
await page.getByRole('button', { name: /GENOME/i }).click()
await page.waitForTimeout(1200)
const displayed = await page.locator('.gene-group').filter({ hasText: 'ANIMAL ADAPTATIONS' }).innerText()
const genome = await page.evaluate(() => JSON.parse(localStorage.getItem('helix-forge-save-v1')).creatures.at(-1).genome)
for (const key of ['antlers', 'fins', 'gills']) if (genome[key][0] < .88 || genome[key][1] < .88) throw new Error(`Selected adaptation ${key} missing: ${genome[key]}`)
for (const key of ['antennae', 'carapace', 'pincers']) if (genome[key][0] > .12 || genome[key][1] > .12) throw new Error(`Unselected adaptation ${key} not recessive: ${genome[key]}`)
await page.screenshot({ path: '/tmp/opencode/latest-adaptations.jpg', type: 'jpeg', quality: 62 })
console.log(JSON.stringify({ modalCount: count, fourthCheckboxRejected: !fourthChecked, geneDisplay: displayed, selectedLoci: ['antlers','fins','gills'].map(k => [k, genome[k]]), pageErrors: errors, screenshot: '/tmp/opencode/latest-adaptations.jpg', bytes: (await import('node:fs')).statSync('/tmp/opencode/latest-adaptations.jpg').size }, null, 2))
await browser.close()
if (errors.length) process.exitCode = 1
